                wCos = nextWCos;
            }
        }
    }
    if (invert) {
        for (int i = 0; i < n; i++) {
            a[i] /= n;
        }
    }
    return a;
}

vector<int> multiplyMod(const vector<int>& a, const vector<int>& b, int mod) {
    int need = a.size() + b.size() - 1;
    int size = 1 << (32 - __builtin_clz(need - 1));
    vector<double> A(size, 0), B(size, 0);
    for (int i = 0; i < (int)a.size(); i++) {
        int val = ((a[i] % mod) + mod) % mod;
        A[i] = (val & ((1 << 15) - 1)) + (((val >> 15) & 1) * 0.000001);
    }
    for (int i = 0; i < (int)b.size(); i++) {
        int val = ((b[i] % mod) + mod) % mod;
        B[i] = (val & ((1 << 15) - 1)) + (((val >> 15) & 1) * 0.000001);
    }
    fftTransform(A, false);
    fftTransform(B, false);
    vector<double> FbA(size, 0), FbB(size, 0);
    for (int i = 0; i < size; i++) {
        int j = (size - i) & (size - 1);
